class Solution {
public:
    bool splitArray(vector<int>& nums) {
        int n = nums.size();
        if (n < 7) return false;
        vector<int> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        auto getSum = [&](int l, int r) {
            return prefix[r + 1] - prefix[l];
        };

        for (int j = 3; j < n - 3; j++) {
            unordered_set<int> seen;
            for (int i = 1; i < j - 1; i++) {
                if (getSum(0, i - 1) == getSum(i + 1, j - 1)) {
                    seen.insert(getSum(0, i - 1));
                }
            }
            for (int k = j + 2; k < n - 1; k++) {
                if (getSum(j + 1, k - 1) == getSum(k + 1, n - 1)) {
                    if (seen.count(getSum(j + 1, k - 1))) return true;
                }
            }
        }
        return false;
    }
};

class Solution {
    public boolean splitArray(int[] nums) {
        int n = nums.length;
        if (n < 7) return false;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        for (int j = 3; j < n - 3; j++) {
            java.util.Set<Integer> seen = new java.util.HashSet<>();
            for (int i = 1; i < j - 1; i++) {
                int left = prefix[i] - prefix[0];
                int right = prefix[j] - prefix[i + 1];
                if (left == right) {
                    seen.add(left);
                }
            }
            for (int k = j + 2; k < n - 1; k++) {
                int left = prefix[k] - prefix[j + 1];
                int right = prefix[n] - prefix[k + 1];
                if (left == right && seen.contains(left)) {
                    return true;
                }
            }
        }
        return false;
    }
}

