var splitArray = function(nums) {
    const n = nums.length;
    if (n < 7) return false;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    const getSum = (l, r) => prefix[r + 1] - prefix[l];

    for (let j = 3; j < n - 3; j++) {
        const seen = new Set();
        for (let i = 1; i < j - 1; i++) {
            if (getSum(0, i - 1) === getSum(i + 1, j - 1)) {
                seen.add(getSum(0, i - 1));
            }
        }
        for (let k = j + 2; k < n - 1; k++) {
            if (getSum(j + 1, k - 1) === getSum(k + 1, n - 1)) {
                if (seen.has(getSum(j + 1, k - 1))) {
                    return true;
                }
            }
        }
    }
    return false;
};
